using DriveOS.Modules.Workforce.Domain.LeavePolicies; using DriveOS.SharedKernel.Identifiers; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.Workforce.Infrastructure.Persistence.Configurations;
internal sealed class LeavePolicyConfiguration:IEntityTypeConfiguration<LeavePolicy>{public void Configure(EntityTypeBuilder<LeavePolicy>b){b.ToTable("leave_policies");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new LeavePolicyId(x)).ValueGeneratedNever();b.Property(x=>x.OrganizationId).HasConversion(x=>x.Value,x=>new OrganizationId(x)).IsRequired();b.Property(x=>x.CountryCode).HasMaxLength(2).IsRequired();b.Property(x=>x.Code).HasMaxLength(64).IsRequired();b.Property(x=>x.Name).HasMaxLength(160).IsRequired();b.Property(x=>x.Category).HasConversion<string>().HasMaxLength(48).IsRequired();b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(24).IsRequired();b.Property(x=>x.CreatedByUserId).HasConversion(x=>x==null?(Guid?)null:x.Value.Value,x=>x==null?null:new UserId(x.Value));b.Property(x=>x.LastModifiedByUserId).HasConversion(x=>x==null?(Guid?)null:x.Value.Value,x=>x==null?null:new UserId(x.Value));b.HasIndex(x=>new{x.OrganizationId,x.CountryCode,x.Code}).IsUnique();b.HasIndex(x=>new{x.OrganizationId,x.CountryCode,x.Status});}}
